<div class="page-head"><div><div class="page-kicker">Ledger</div><h1 class="page-title">Transaction history</h1><p class="page-subtitle">Every confirmed movement stays traceable. Corrections are voids, not deletions.</p></div><div class="head-actions"><a class="btn" href="<?=site_url('inventory')?>">← Current stock</a></div></div>
<div class="card"><form class="toolbar" method="get"><div style="display:flex;gap:9px;flex-wrap:wrap;flex:1"><input style="min-width:230px" class="filters" name="q" value="<?=esc($q??'')?>" placeholder="Search transaction, reference, party or user"><select name="type"><option value="">All movement types</option><option value="IN" <?=($type??'')==='IN'?'selected':''?>>IN</option><option value="OUT" <?=($type??'')==='OUT'?'selected':''?>>OUT</option></select><select name="status"><option value="">All statuses</option><option value="CONFIRMED" <?=($status??'')==='CONFIRMED'?'selected':''?>>Confirmed</option><option value="VOID" <?=($status??'')==='VOID'?'selected':''?>>Void</option></select><input type="date" name="from" value="<?=esc($from??'')?>"><input type="date" name="to" value="<?=esc($to??'')?>"><button class="btn primary small" type="submit">Filter</button></div></form><div class="table-wrap"><table class="table"><thead><tr><th>Transaction</th><th>Type</th><th>Reference</th><th>Party</th><th>User</th><th>Status</th><th>Date</th><th></th></tr></thead><tbody><?php if(!$transactions): ?><tr><td colspan="8"><div class="empty"><strong>No transactions match these filters</strong>Try clearing one of the filters.</div></td></tr><?php else: foreach($transactions as $t): ?><tr><td class="mono"><?=esc($t['transaction_no'])?></td><td><span class="badge <?=$t['type']==='IN'?'success':'danger'?>"><?=esc($t['type'])?></span></td><td><?=esc($t['reference_no']??'—')?></td><td><?=esc($t['party_name']??'—')?></td><td><?=esc($t['user_name']??'—')?></td><td><span class="badge <?=$t['status']==='VOID'?'neutral':'success'?>"><?=esc($t['status'])?></span></td><td><?=esc($t['created_at'])?></td><td><a class="btn small" href="<?=site_url('inventory/transactions/'.$t['id'])?>">View</a><?php if($canVoid&&$t['status']!=='VOID'): ?><a class="btn small ghost" href="#" data-void-form="<?=$t['id']?>">Void</a><form id="void-form-<?=$t['id']?>" method="post" action="<?=site_url('transactions/'.$t['id'].'/void')?>" style="display:none"><?=csrf_field()?><input name="reason" id="void-reason-<?=$t['id']?>"></form><script>document.querySelector('[data-void-form="<?=$t['id']?>"]')?.addEventListener('click',function(e){e.preventDefault();const reason=prompt('Enter the reason for voiding this transaction:');if(reason&&reason.trim()){document.getElementById('void-reason-<?=$t['id']?>').value=reason.trim();document.getElementById('void-form-<?=$t['id']?>').submit();}});</script><?php endif; ?></td></tr><?php endforeach; endif; ?></tbody></table></div></div>
